// Requests share a prototype that carries a symbol-keyed marker and a
// method, as effect's Request.tagged constructors do.
export const ReqTypeId = Symbol.for("reqtag/Req");
const proto = {
  [ReqTypeId]: true,
  describe() {
    return `${this._tag}(${this.value})`;
  },
};
export function tagged(tag) {
  return (args) => Object.assign(Object.create(proto), args, { _tag: tag });
}
export function run(request) {
  return request[ReqTypeId] === true ? request.describe() : "not a request";
}
